# Mercury: `claude` runs under the Claude account selected in Mercury (bash).
# Generated by Mercury and rewritten when it changes.
#
# Every run re-reads $MERCURY_DATA_ROOT/claude-profiles/selected-host (an absolute config directory), so switching accounts
# in Mercury applies to the next `claude` without reopening the terminal. An empty or missing pointer keeps your
# default login. A CLAUDE_CONFIG_DIR you set yourself wins, and so does a claude function you defined yourself: this file then
# defines nothing. Running under a Mercury account unsets API-key variables that would override its login.
if ! typeset -f claude >/dev/null 2>&1; then
  function claude {
    local __mercury_pointer __mercury_home=""
    if [[ -n "${CLAUDE_CONFIG_DIR:-}" || -z "${MERCURY_DATA_ROOT:-}" ]]; then
      command claude "$@"
      return
    fi
    __mercury_pointer="${MERCURY_DATA_ROOT}/claude-profiles/selected-host"
    if [[ -r "$__mercury_pointer" ]]; then
      __mercury_home="$(cat -- "$__mercury_pointer" 2>/dev/null)"
    fi
    if [[ -z "$__mercury_home" ]]; then
      command claude "$@"
      return
    fi
    # Refuse rather than run under the wrong account.
    if [[ "$__mercury_home" != /* ]]; then
      printf '%s\n' "mercury: the selected Claude account is not an absolute path ($__mercury_pointer); claude not started." >&2
      return 1
    fi
    # A private folder, like the one Mercury creates for an account.
    [[ -d "$__mercury_home" ]] || mkdir -p -m 700 -- "$__mercury_home" 2>/dev/null
    (
      unset ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN AWS_BEARER_TOKEN_BEDROCK
      export CLAUDE_CONFIG_DIR="$__mercury_home"
      command claude "$@"
    )
  }
fi
